// =====================================================
// CODE NODE: Select Model
// Purpose: Choose between FREE Gemini and Premium Claude
// Logic: Use free model by default, upgrade for high-value leads
// =====================================================

// Get data from previous node
const inputData = $input.first().json;

// Default to FREE Gemini model (zero cost)
let selectedModel = 'google/gemini-2.0-flash-exp:free';

// Extract lead qualification data
const leadData = inputData.leadData || {};
const estimatedCost = leadData.estimatedCost || leadData.lastCalculatedCost || 0;
const conversationHistory = inputData.conversationHistory || [];
const messageCount = conversationHistory.length;

// Qualification thresholds
const HIGH_VALUE_THRESHOLD = 5000; // $5K+/month waste = high value
const ENGAGED_THRESHOLD = 6; // 6+ messages = engaged lead

// Determine if this is a high-value, engaged lead
const isHighValue = estimatedCost > HIGH_VALUE_THRESHOLD;
const isEngaged = messageCount > ENGAGED_THRESHOLD;

// Upgrade decision logic
let upgradeReason = null;

if (isHighValue && isEngaged) {
  // Worth spending ~$0.15 on Claude for a potential $10K+ client
  selectedModel = 'anthropic/claude-sonnet-4';
  upgradeReason = 'high_value_engaged_lead';
} else if (estimatedCost > 10000 && messageCount > 4) {
  // Very high value, slightly less engaged - still worth premium
  selectedModel = 'anthropic/claude-sonnet-4';
  upgradeReason = 'very_high_value_lead';
}

// Build conversation messages array for OpenRouter
const messages = [
  {
    role: 'system',
    content: inputData.systemPrompt
  }
];

// Add conversation history
if (conversationHistory && conversationHistory.length > 0) {
  for (const msg of conversationHistory) {
    messages.push({
      role: msg.role,
      content: msg.content
    });
  }
}

// Add current user message
if (inputData.userMessage) {
  messages.push({
    role: 'user',
    content: inputData.userMessage
  });
}

return [{
  json: {
    selectedModel,
    isHighValue,
    isEngaged,
    upgradeReason,
    messageCount,
    estimatedCost,
    messages,
    userName: inputData.userName,
    userEmail: inputData.userEmail,
    leadData: inputData.leadData,
    timestamp: inputData.timestamp
  }
}];

// =====================================================
// CODE NODE: Process OpenRouter Response
// Purpose: Parse AI response, validate JSON, prepare for output
// =====================================================

// Get the API response
const apiResponse = $input.first().json;

// Extract the AI's response content (OpenAI-compatible format)
const content = apiResponse?.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('No response content from OpenRouter API. Response: ' + JSON.stringify(apiResponse));
}

// Parse the JSON response from the AI
let parsedResponse;
try {
  parsedResponse = JSON.parse(content);
} catch (parseError) {
  // If JSON parsing fails, create a fallback response
  console.error('Failed to parse AI response as JSON:', parseError.message);
  console.error('Raw content:', content);

  // Try to extract a reply from the content
  let fallbackReply = content;

  // If content looks like it has a reply buried in it, try to extract
  const replyMatch = content.match(/"reply"\s*:\s*"([^"]+)"/i);
  if (replyMatch) {
    fallbackReply = replyMatch[1];
  }

  parsedResponse = {
    reply: fallbackReply.substring(0, 500), // Truncate if too long
    quickReplies: [],
    showCostCard: false,
    costAmount: 0,
    showCalendar: false
  };
}

// Validate and sanitize required fields
if (!parsedResponse.reply || typeof parsedResponse.reply !== 'string') {
  parsedResponse.reply = "I'm here to help! Could you tell me more about your operational challenges?";
}

// Ensure arrays and booleans have correct types
parsedResponse.quickReplies = Array.isArray(parsedResponse.quickReplies) 
  ? parsedResponse.quickReplies.slice(0, 4) // Max 4 quick replies
  : [];

parsedResponse.showCostCard = Boolean(parsedResponse.showCostCard);
parsedResponse.showCalendar = Boolean(parsedResponse.showCalendar);
parsedResponse.costAmount = Number(parsedResponse.costAmount) || 0;

// Get metadata from earlier nodes using $() syntax
let userName = null;
let userEmail = null;
let leadData = {};
let selectedModel = 'google/gemini-2.0-flash-exp:free';

try {
  const selectModelData = $('Code - Select Model').first().json;
  userName = selectModelData.userName;
  userEmail = selectModelData.userEmail;
  leadData = selectModelData.leadData || {};
  selectedModel = selectModelData.selectedModel;
} catch (e) {
  console.error('Could not retrieve data from previous nodes:', e.message);
}

// Update lead data with calculated cost
if (parsedResponse.costAmount > 0) {
  leadData.lastCalculatedCost = parsedResponse.costAmount;
}

// Determine qualification status
// Qualified if: calendar shown OR cost > $3000
const isQualified = parsedResponse.showCalendar || parsedResponse.costAmount > 3000;

// Get usage info from API response
const usage = apiResponse?.usage || {};
const tokensUsed = {
  prompt: usage.prompt_tokens || 0,
  completion: usage.completion_tokens || 0,
  total: usage.total_tokens || 0
};

return [{
  json: {
    // Response to send back to chat interface
    reply: parsedResponse.reply,
    quickReplies: parsedResponse.quickReplies,
    showCostCard: parsedResponse.showCostCard,
    costAmount: parsedResponse.costAmount,
    showCalendar: parsedResponse.showCalendar,

    // Metadata for lead capture and analytics
    userName,
    userEmail,
    leadData,
    isQualified,
    modelUsed: selectedModel,
    tokensUsed,
    timestamp: new Date().toISOString()
  }
}];
